      '<button type="button" class="tc-x" aria-label="Close chart">✕</button></div><iframe title="Trade chart" loading="eager"></iframe></div>';
    document.body.appendChild(modal);
    frame=modal.querySelector('iframe');title=modal.querySelector('.tc-bar b');full=modal.querySelector('.tc-full');
